UPDATE WMSSTCK;
   SET TOT_QTY = NVL(TOT_QTY,0) +  #{INV_QTY},		
		  AVAIL_QTY = NVL(AVAIL_QTY,0) + #{INV_QTY},	
		  STC_SELLER_PRICE = DECODE(NVL(AVAIL_QTY,0)+ #{INV_QTY},0,0,NVL(STC_SELLER_PRICE,0))	
WHERE WAREHOUSE_CODE = #{st_warehouse_code} 	
  AND STDCATLG_ID =   #{STDCATLG_ID} 			
  AND AGENT = DECODE(#{PROCESS_TYPE},'1','KRKORE0001','3',(SELECT WAREHOUSE_CODE FROM ICOMPODT WHERE BUYER =  #{BUYER} AND PO_NO =  #{PO_NO} AND PO_SEQ =#{PO_SEQ}) )


UPDATE ICOMIVDT SET WMS_GR_QTY = 0, WMS_IVK_QTY = 0, 
                    CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), 
                    CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS') 
 WHERE BUYER  = #{BUYER}             
   AND PO_NO  = #{PO_NO}  
   AND PO_SEQ =  #{PO_SEQ}
